using System;

namespace DailyTaskManager.Core.Localization
{
    /// <summary>Translations of the Help page (columns: bs, hr, sr, de, tr)</summary>
    internal static class HelpTranslations
    {
        public static void Register(Action<string, string, string, string, string, string> a)
        {
            // Key caps
            a("Ctrl", "Ctrl", "Ctrl", "Ctrl", "Strg", "Ctrl");
            a("Up", "Gore", "Gore", "Gore", "Hoch", "Yukarı");
            a("Down", "Dolje", "Dolje", "Dole", "Runter", "Aşağı");
            a("Double-click", "Dvoklik", "Dvoklik", "Dvoklik", "Doppelklick", "Çift tıklama");

            // Keyboard shortcuts
            a("Keyboard shortcuts", "Tastaturne prečice", "Tipkovnički prečaci", "Prečice na tastaturi", "Tastenkürzel", "Klavye kısayolları");
            a("Work faster without the mouse", "Radite brže bez miša", "Radite brže bez miša", "Radite brže bez miša", "Schneller arbeiten ohne Maus", "Fare olmadan daha hızlı çalışın");
            a("New entry", "Novi unos", "Novi unos", "Novi unos", "Neuer Eintrag", "Yeni kayıt");
            a("Opens the Add Entry dialog from the Daily Tasks page.", "Otvara dijalog za dodavanje unosa sa stranice Dnevni zadaci.", "Otvara dijalog za dodavanje unosa sa stranice Dnevni zadaci.", "Otvara dijalog za dodavanje unosa sa stranice Dnevni zadaci.", "Öffnet den Dialog zum Hinzufügen eines Eintrags auf der Seite Tagesaufgaben.", "Günlük Görevler sayfasından kayıt ekleme penceresini açar.");
            a("Search", "Pretraga", "Pretraga", "Pretraga", "Suche", "Ara");
            a("Jumps to the search box in the list view and selects what is typed there.", "Prelazi na polje za pretragu u prikazu liste i označava ono što je tamo upisano.", "Prelazi na polje za pretragu u prikazu popisa i označava ono što je tamo upisano.", "Prelazi na polje za pretragu u prikazu liste i označava ono što je tamo upisano.", "Springt zum Suchfeld in der Listenansicht und markiert den dort eingegebenen Text.", "Liste görünümündeki arama kutusuna gider ve orada yazılanı seçer.");
            a("Undo a delete", "Poništi brisanje", "Poništi brisanje", "Poništi brisanje", "Löschen rückgängig machen", "Silmeyi geri al");
            a("Brings back the entry you just deleted. The Undo bar at the bottom stays for about 8 seconds; the shortcut works while it is shown.", "Vraća unos koji ste upravo obrisali. Traka Poništi pri dnu ostaje oko 8 sekundi; prečica radi dok je prikazana.", "Vraća unos koji ste upravo izbrisali. Traka Poništi pri dnu ostaje oko 8 sekundi; prečac radi dok je prikazana.", "Vraća unos koji ste upravo obrisali. Traka Poništi pri dnu ostaje oko 8 sekundi; prečica radi dok je prikazana.", "Stellt den soeben gelöschten Eintrag wieder her. Die Leiste „Rückgängig“ unten bleibt etwa 8 Sekunden sichtbar; das Tastenkürzel funktioniert, solange sie angezeigt wird.", "Az önce sildiğiniz kaydı geri getirir. Alttaki Geri al çubuğu yaklaşık 8 saniye görünür kalır; kısayol görünürken çalışır.");
            a("Save an inline edit", "Spremi izmjenu na mjestu", "Spremi izmjenu na mjestu", "Sačuvaj izmenu na mestu", "Direktbearbeitung speichern", "Satır içi düzenlemeyi kaydet");
            a("Saves the description you are editing in place. Plain Enter adds a new line there, because descriptions can have several lines.", "Sprema opis koji uređujete na mjestu. Običan Enter tamo dodaje novi red, jer opisi mogu imati više redova.", "Sprema opis koji uređujete na mjestu. Običan Enter tamo dodaje novi redak, jer opisi mogu imati više redaka.", "Čuva opis koji menjate na mestu. Običan Enter tamo dodaje novi red, jer opisi mogu imati više redova.", "Speichert die Beschreibung, die Sie direkt bearbeiten. Die Eingabetaste allein fügt dort eine neue Zeile ein, da Beschreibungen mehrere Zeilen haben können.", "Yerinde düzenlediğiniz açıklamayı kaydeder. Yalnızca Enter orada yeni satır ekler, çünkü açıklamalar birden çok satırdan oluşabilir.");
            a("Save hours", "Spremi sate", "Spremi sate", "Sačuvaj sate", "Stunden speichern", "Saatleri kaydet");
            a("Saves the hours you are editing in place.", "Sprema sate koje uređujete na mjestu.", "Sprema sate koje uređujete na mjestu.", "Čuva sate koje menjate na mestu.", "Speichert die Stunden, die Sie direkt bearbeiten.", "Yerinde düzenlediğiniz saatleri kaydeder.");
            a("Discards an inline edit without saving.", "Odbacuje izmjenu na mjestu bez spremanja.", "Odbacuje izmjenu na mjestu bez spremanja.", "Odbacuje izmenu na mestu bez čuvanja.", "Verwirft eine Direktbearbeitung ohne Speichern.", "Satır içi düzenlemeyi kaydetmeden iptal eder.");

            // Daily Tasks
            a("Two ways to look at the same entries", "Dva načina za pregled istih unosa", "Dva načina za pregled istih unosa", "Dva načina za pregled istih unosa", "Zwei Ansichten derselben Einträge", "Aynı kayıtlara bakmanın iki yolu");
            a("Week view", "Sedmični prikaz", "Tjedni prikaz", "Sedmični prikaz", "Wochenansicht", "Haftalık görünüm");
            a("The default. Seven columns, Monday to Sunday, each with its entries and the day's hours. Use the arrow buttons to move between weeks and \"This week\" to jump back. Today is outlined.", "Zadani prikaz. Sedam kolona, od ponedjeljka do nedjelje, svaka s unosima i satima tog dana. Strelicama se krećete između sedmica, a \"Ova sedmica\" vraća na trenutnu. Današnji dan je označen okvirom.", "Zadani prikaz. Sedam stupaca, od ponedjeljka do nedjelje, svaki s unosima i satima tog dana. Strelicama se krećete između tjedana, a \"Ovaj tjedan\" vraća na trenutni. Današnji dan označen je okvirom.", "Podrazumevani prikaz. Sedam kolona, od ponedeljka do nedelje, svaka sa unosima i satima tog dana. Strelicama se krećete između sedmica, a \"Ova sedmica\" vraća na trenutnu. Današnji dan je označen okvirom.", "Die Standardansicht. Sieben Spalten, Montag bis Sonntag, jeweils mit den Einträgen und Stunden des Tages. Mit den Pfeiltasten wechseln Sie die Woche, mit \"Diese Woche\" springen Sie zurück. Heute ist umrandet.", "Varsayılan görünüm. Pazartesiden pazara yedi sütun; her biri o günün kayıtlarını ve saatlerini gösterir. Haftalar arasında gezinmek için oklar, geri dönmek için \"Bu hafta\" kullanılır. Bugün çerçeveli gösterilir.");
            a("List view", "Prikaz liste", "Prikaz popisa", "Prikaz liste", "Listenansicht", "Liste görünümü");
            a("Switch with the Week / List buttons in the header. The list adds search, date range and client filters, paging and bulk actions.", "Prebacujte se tipkama Sedmica / Lista u zaglavlju. Lista dodaje pretragu, filtere po datumu i klijentu, straničenje i skupne radnje.", "Prebacujte se gumbima Tjedan / Popis u zaglavlju. Popis dodaje pretragu, filtre po datumu i klijentu, straničenje i skupne radnje.", "Prebacujte se dugmadima Sedmica / Lista u zaglavlju. Lista dodaje pretragu, filtere po datumu i klijentu, straničenje i grupne radnje.", "Wechseln Sie mit den Schaltflächen Woche / Liste in der Kopfzeile. Die Liste bietet Suche, Datums- und Kundenfilter, Seitenwechsel und Sammelaktionen.", "Üstbilgideki Hafta / Liste düğmeleriyle geçiş yapın. Liste; arama, tarih aralığı ve müşteri filtreleri, sayfalama ve toplu işlemler ekler.");
            a("Add for a day", "Dodavanje za dan", "Dodavanje za dan", "Dodavanje za dan", "Für einen Tag hinzufügen", "Bir gün için ekleme");
            a("Press Add at the bottom of a day column to create an entry for that exact day.", "Pritisnite Dodaj na dnu kolone dana da kreirate unos za taj tačan dan.", "Pritisnite Dodaj na dnu stupca dana da izradite unos za taj točan dan.", "Pritisnite Dodaj na dnu kolone dana da napravite unos za taj tačan dan.", "Drücken Sie unten in einer Tagesspalte auf Hinzufügen, um einen Eintrag für genau diesen Tag zu erstellen.", "Tam o gün için kayıt oluşturmak üzere gün sütununun altındaki Ekle'ye basın.");
            a("Edit an entry", "Uređivanje unosa", "Uređivanje unosa", "Izmena unosa", "Eintrag bearbeiten", "Kaydı düzenleme");
            a("Click the text of an entry in the week view, or use the pencil in the list view.", "Kliknite na tekst unosa u sedmičnom prikazu ili koristite olovku u prikazu liste.", "Kliknite na tekst unosa u tjednom prikazu ili koristite olovku u prikazu popisa.", "Kliknite na tekst unosa u sedmičnom prikazu ili koristite olovku u prikazu liste.", "Klicken Sie in der Wochenansicht auf den Text eines Eintrags oder nutzen Sie in der Listenansicht den Stift.", "Haftalık görünümde bir kaydın metnine tıklayın veya liste görünümünde kalemi kullanın.");
            a("Edit in place", "Uređivanje na mjestu", "Uređivanje na mjestu", "Izmena na mestu", "Direkt bearbeiten", "Yerinde düzenleme");
            a("In the list view, double-click a description or the hours badge to edit it right there. Click away to save, or press Esc to cancel.", "U prikazu liste dvaput kliknite opis ili oznaku sati da ga uredite odmah tamo. Kliknite izvan polja da spremite ili pritisnite Esc da otkažete.", "U prikazu popisa dvaput kliknite opis ili oznaku sati da ga uredite odmah tamo. Kliknite izvan polja da spremite ili pritisnite Esc da odustanete.", "U prikazu liste dvaput kliknite opis ili oznaku sati da ga izmenite odmah tamo. Kliknite van polja da sačuvate ili pritisnite Esc da otkažete.", "Doppelklicken Sie in der Listenansicht auf eine Beschreibung oder das Stundenfeld, um sie direkt zu bearbeiten. Klicken Sie daneben, um zu speichern, oder drücken Sie Esc zum Abbrechen.", "Liste görünümünde, bir açıklamaya veya saat rozetine çift tıklayarak orada düzenleyin. Kaydetmek için dışarı tıklayın, iptal için Esc'ye basın.");
            a("Duplicate", "Dupliciranje", "Dupliciranje", "Dupliranje", "Duplizieren", "Kopyalama");
            a("The copy button opens the Add dialog pre-filled with that entry, dated today. Handy for recurring work.", "Dugme za kopiranje otvara dijalog za dodavanje popunjen tim unosom, s današnjim datumom. Praktično za ponavljajući rad.", "Gumb za kopiranje otvara dijalog za dodavanje popunjen tim unosom, s današnjim datumom. Praktično za ponavljajući rad.", "Dugme za kopiranje otvara dijalog za dodavanje popunjen tim unosom, sa današnjim datumom. Praktično za ponavljajući rad.", "Die Kopieren-Schaltfläche öffnet den Hinzufügen-Dialog mit diesem Eintrag, datiert auf heute. Praktisch für wiederkehrende Arbeit.", "Kopyala düğmesi, bugünün tarihiyle o kayıtla doldurulmuş ekleme penceresini açar. Tekrarlayan işler için kullanışlıdır.");
            a("Delete and undo", "Brisanje i poništavanje", "Brisanje i poništavanje", "Brisanje i poništavanje", "Löschen und rückgängig machen", "Silme ve geri alma");
            a("Deleting does not ask for confirmation. Use the Undo button in the bar that appears, or press Ctrl+Z.", "Brisanje ne traži potvrdu. Koristite dugme Poništi u traci koja se pojavi ili pritisnite Ctrl+Z.", "Brisanje ne traži potvrdu. Koristite gumb Poništi u traci koja se pojavi ili pritisnite Ctrl+Z.", "Brisanje ne traži potvrdu. Koristite dugme Poništi u traci koja se pojavi ili pritisnite Ctrl+Z.", "Beim Löschen wird nicht nachgefragt. Nutzen Sie die Schaltfläche Rückgängig in der eingeblendeten Leiste oder drücken Sie Strg+Z.", "Silme işlemi onay istemez. Görünen çubuktaki Geri al düğmesini kullanın veya Ctrl+Z'ye basın.");
            a("Quick add", "Brzi unos", "Brzi unos", "Brzi unos", "Schnell hinzufügen", "Hızlı ekle");
            a("The Quick add button lists your saved templates. One click creates an entry from a template.", "Dugme Brzi unos prikazuje vaše sačuvane šablone. Jedan klik kreira unos iz šablona.", "Gumb Brzi unos prikazuje vaše spremljene predloške. Jedan klik izrađuje unos iz predloška.", "Dugme Brzi unos prikazuje vaše sačuvane šablone. Jedan klik pravi unos iz šablona.", "Die Schaltfläche Schnell hinzufügen listet Ihre gespeicherten Vorlagen. Ein Klick erstellt einen Eintrag aus einer Vorlage.", "Hızlı ekle düğmesi kayıtlı şablonlarınızı listeler. Tek tıkla şablondan kayıt oluşturulur.");
            a("Assign a client in bulk", "Skupna dodjela klijenta", "Skupna dodjela klijenta", "Grupna dodela klijenta", "Kunden gesammelt zuweisen", "Toplu müşteri atama");
            a("In the list view, filter the entries you want and press Assign client to set (or remove) the client of all of them at once.", "U prikazu liste filtrirajte željene unose i pritisnite Dodijeli klijenta da svima odjednom postavite (ili uklonite) klijenta.", "U prikazu popisa filtrirajte željene unose i pritisnite Dodijeli klijenta da svima odjednom postavite (ili uklonite) klijenta.", "U prikazu liste filtrirajte željene unose i pritisnite Dodeli klijenta da svima odjednom postavite (ili uklonite) klijenta.", "Filtern Sie in der Listenansicht die gewünschten Einträge und drücken Sie Kunde zuweisen, um den Kunden aller auf einmal zu setzen (oder zu entfernen).", "Liste görünümünde istediğiniz kayıtları filtreleyin ve hepsinin müşterisini tek seferde atamak (veya kaldırmak) için Müşteri ata'ya basın.");
            a("Statistics", "Statistika", "Statistika", "Statistika", "Statistik", "İstatistikler");
            a("The cards at the top show today, this week (Monday to Sunday), all entries and your 30-day average against the 7 hour target.", "Kartice na vrhu prikazuju danas, ovu sedmicu (od ponedjeljka do nedjelje), sve unose i vaš 30-dnevni prosjek u odnosu na cilj od 7 sati.", "Kartice na vrhu prikazuju danas, ovaj tjedan (od ponedjeljka do nedjelje), sve unose i vaš 30-dnevni prosjek u odnosu na cilj od 7 sati.", "Kartice na vrhu prikazuju danas, ovu sedmicu (od ponedeljka do nedelje), sve unose i vaš 30-dnevni prosek u odnosu na cilj od 7 sati.", "Die Karten oben zeigen heute, diese Woche (Montag bis Sonntag), alle Einträge und Ihren 30-Tage-Durchschnitt im Vergleich zum Ziel von 7 Stunden.", "Üstteki kartlar bugünü, bu haftayı (pazartesi-pazar), tüm kayıtları ve 7 saatlik hedefe karşı 30 günlük ortalamanızı gösterir.");

            // Entry dialog
            a("Adding and editing an entry", "Dodavanje i uređivanje unosa", "Dodavanje i uređivanje unosa", "Dodavanje i izmena unosa", "Eintrag hinzufügen und bearbeiten", "Kayıt ekleme ve düzenleme");
            a("What the entry dialog can do", "Šta dijalog unosa može", "Što dijalog unosa može", "Šta dijalog unosa može", "Was der Eintragsdialog kann", "Kayıt penceresinin yapabilecekleri");
            a("Description suggestions", "Prijedlozi opisa", "Prijedlozi opisa", "Predlozi opisa", "Beschreibungsvorschläge", "Açıklama önerileri");
            a("While you type, earlier descriptions are suggested. Use the Up and Down arrows with Enter to pick one, or Esc to hide the list.", "Dok tipkate, predlažu se raniji opisi. Strelicama gore i dolje i Enterom odaberite jedan, ili Esc da sakrijete listu.", "Dok tipkate, predlažu se raniji opisi. Strelicama gore i dolje i Enterom odaberite jedan, ili Esc da sakrijete popis.", "Dok kucate, predlažu se raniji opisi. Strelicama gore i dole i Enterom izaberite jedan, ili Esc da sakrijete listu.", "Beim Tippen werden frühere Beschreibungen vorgeschlagen. Wählen Sie mit den Pfeiltasten und der Eingabetaste einen aus oder blenden Sie die Liste mit Esc aus.", "Yazarken önceki açıklamalar önerilir. Birini seçmek için yukarı/aşağı oklarını ve Enter'ı, listeyi gizlemek için Esc'yi kullanın.");
            a("The Dictate button turns your voice into the description (shown when a microphone is available). Speak in phrases: each pause adds the text spoken so far. It runs offline with the Whisper model, which downloads once (about 190 MB) the first time. Pick your language under Settings, Dictation for the best accuracy.", "Dugme Diktiraj pretvara vaš glas u opis (prikazuje se kada je mikrofon dostupan). Govorite u frazama: svaka pauza dodaje do tada izgovoreni tekst. Radi bez interneta s Whisper modelom koji se preuzima jednom (oko 190 MB) pri prvom korištenju. Za najbolju tačnost odaberite svoj jezik u Postavke, Diktiranje.", "Gumb Diktiraj pretvara vaš glas u opis (prikazuje se kada je mikrofon dostupan). Govorite u frazama: svaka stanka dodaje do tada izgovoreni tekst. Radi izvan mreže s Whisper modelom koji se preuzima jednom (oko 190 MB) pri prvom korištenju. Za najbolju točnost odaberite svoj jezik u Postavke, Diktiranje.", "Dugme Diktiraj pretvara vaš glas u opis (prikazuje se kada je mikrofon dostupan). Govorite u frazama: svaka pauza dodaje do tada izgovoreni tekst. Radi bez interneta sa Whisper modelom koji se preuzima jednom (oko 190 MB) pri prvom korišćenju. Za najbolju tačnost izaberite svoj jezik u Podešavanja, Diktiranje.", "Die Schaltfläche Diktieren wandelt Ihre Stimme in die Beschreibung um (sichtbar, wenn ein Mikrofon verfügbar ist). Sprechen Sie in Sätzen: Jede Pause fügt den bisher gesprochenen Text hinzu. Es läuft offline mit dem Whisper-Modell, das beim ersten Mal einmalig (ca. 190 MB) heruntergeladen wird. Wählen Sie für die beste Genauigkeit Ihre Sprache unter Einstellungen, Diktat.", "Dikte et düğmesi sesinizi açıklamaya dönüştürür (mikrofon varsa görünür). Cümleler halinde konuşun: her duraklama o ana kadar söylenen metni ekler. Whisper modeliyle çevrimdışı çalışır; model ilk seferde bir kez (yaklaşık 190 MB) indirilir. En iyi doğruluk için Ayarlar, Dikte bölümünden dilinizi seçin.");
            a("Clients", "Klijenti", "Klijenti", "Klijenti", "Kunden", "Müşteriler");
            a("Pick an existing client, or type a new name in the second field to create it with the entry.", "Odaberite postojećeg klijenta ili upišite novo ime u drugo polje da ga kreirate zajedno s unosom.", "Odaberite postojećeg klijenta ili upišite novo ime u drugo polje da ga izradite zajedno s unosom.", "Izaberite postojećeg klijenta ili upišite novo ime u drugo polje da ga napravite zajedno sa unosom.", "Wählen Sie einen vorhandenen Kunden oder tippen Sie im zweiten Feld einen neuen Namen, um ihn mit dem Eintrag anzulegen.", "Mevcut bir müşteri seçin veya ikinci alana yeni bir ad yazarak kayıtla birlikte oluşturun.");
            a("Templates", "Šabloni", "Predlošci", "Šabloni", "Vorlagen", "Şablonlar");
            a("Tick \"Save as a template for quick add\" to reuse an entry later. A saved template can also be picked at the top of the dialog.", "Označite \"Sačuvaj kao šablon za brzi unos\" da unos kasnije ponovo iskoristite. Sačuvani šablon možete odabrati i na vrhu dijaloga.", "Označite \"Spremi kao predložak za brzi unos\" da unos kasnije ponovno iskoristite. Spremljeni predložak možete odabrati i na vrhu dijaloga.", "Označite \"Sačuvaj kao šablon za brzi unos\" da unos kasnije ponovo iskoristite. Sačuvani šablon možete izabrati i na vrhu dijaloga.", "Aktivieren Sie \"Als Vorlage für schnelles Hinzufügen speichern\", um einen Eintrag später wiederzuverwenden. Eine gespeicherte Vorlage lässt sich auch oben im Dialog auswählen.", "Bir kaydı sonra yeniden kullanmak için \"Hızlı ekleme için şablon olarak kaydet\" seçeneğini işaretleyin. Kayıtlı şablon, pencerenin üstünden de seçilebilir.");

            // Calendar
            a("See which days are missing hours", "Pogledajte kojim danima nedostaju sati", "Pogledajte kojim danima nedostaju sati", "Pogledajte kojim danima nedostaju sati", "Sehen Sie, an welchen Tagen Stunden fehlen", "Hangi günlerde saat eksik olduğunu görün");
            a("Colours", "Boje", "Boje", "Boje", "Farben", "Renkler");
            a("Green days have 7 hours or more, amber days less than that, and days marked as missing are working days without an entry.", "Zeleni dani imaju 7 sati ili više, žuti dani manje od toga, a dani označeni kao nedostajući su radni dani bez unosa.", "Zeleni dani imaju 7 sati ili više, žuti dani manje od toga, a dani označeni kao nedostajući su radni dani bez unosa.", "Zeleni dani imaju 7 sati ili više, žuti dani manje od toga, a dani označeni kao nedostajući su radni dani bez unosa.", "Grüne Tage haben 7 Stunden oder mehr, gelbe Tage weniger, und als fehlend markierte Tage sind Arbeitstage ohne Eintrag.", "Yeşil günlerde 7 saat veya daha fazlası vardır, sarı günlerde daha azı; eksik işaretli günler kaydı olmayan iş günleridir.");
            a("Click a day", "Klik na dan", "Klik na dan", "Klik na dan", "Auf einen Tag klicken", "Bir güne tıklama");
            a("Adds an entry for that day, or opens the existing entry for editing.", "Dodaje unos za taj dan ili otvara postojeći unos za uređivanje.", "Dodaje unos za taj dan ili otvara postojeći unos za uređivanje.", "Dodaje unos za taj dan ili otvara postojeći unos za izmenu.", "Fügt einen Eintrag für diesen Tag hinzu oder öffnet den vorhandenen zum Bearbeiten.", "O gün için kayıt ekler veya mevcut kaydı düzenlemek üzere açar.");

            // Reports
            a("Reports and exports", "Izvještaji i izvozi", "Izvješća i izvozi", "Izveštaji i izvozi", "Berichte und Exporte", "Raporlar ve dışa aktarmalar");
            a("Hand your hours to someone else", "Predajte svoje sate nekom drugom", "Predajte svoje sate nekom drugom", "Predajte svoje sate nekom drugom", "Geben Sie Ihre Stunden weiter", "Saatlerinizi başkasına iletin");
            a("Choose a month and client in Reports, then export a PDF, Word or Excel work order.", "Odaberite mjesec i klijenta u Izvještajima, zatim izvezite radni nalog u PDF, Word ili Excel.", "Odaberite mjesec i klijenta u Izvješćima, zatim izvezite radni nalog u PDF, Word ili Excel.", "Izaberite mesec i klijenta u Izveštajima, zatim izvezite radni nalog u PDF, Word ili Excel.", "Wählen Sie in Berichte einen Monat und Kunden und exportieren Sie dann einen Arbeitsauftrag als PDF, Word oder Excel.", "Raporlar'da bir ay ve müşteri seçin, ardından PDF, Word veya Excel iş emri dışa aktarın.");
            a("Fills the hours of the chosen month into an invoice with your rate, VAT and payment note.", "Unosi sate odabranog mjeseca u račun s vašom cijenom, PDV-om i napomenom o plaćanju.", "Unosi sate odabranog mjeseca u račun s vašom cijenom, PDV-om i napomenom o plaćanju.", "Unosi sate izabranog meseca u fakturu sa vašom cenom, PDV-om i napomenom o plaćanju.", "Überträgt die Stunden des gewählten Monats in eine Rechnung mit Ihrem Satz, der MwSt. und dem Zahlungshinweis.", "Seçilen ayın saatlerini ücretiniz, KDV ve ödeme notunuzla bir faturaya aktarır.");
            a("Export locations", "Lokacije izvoza", "Lokacije izvoza", "Lokacije izvoza", "Exportorte", "Dışa aktarma konumları");
            a("Settings lets you choose a separate folder for PDF, Word and Excel files.", "U postavkama možete odabrati zasebnu mapu za PDF, Word i Excel datoteke.", "U postavkama možete odabrati zasebnu mapu za PDF, Word i Excel datoteke.", "U podešavanjima možete izabrati zasebnu fasciklu za PDF, Word i Excel datoteke.", "In den Einstellungen können Sie für PDF-, Word- und Excel-Dateien jeweils einen eigenen Ordner wählen.", "Ayarlar'da PDF, Word ve Excel dosyaları için ayrı klasörler seçebilirsiniz.");
            a("Company details", "Podaci o firmi", "Podaci o tvrtki", "Podaci o firmi", "Firmendaten", "Firma bilgileri");
            a("Your header and client details for the documents are kept under Settings, PDF Export Customization.", "Vaše zaglavlje i podaci o klijentu za dokumente nalaze se u Postavke, Prilagodba PDF izvoza.", "Vaše zaglavlje i podaci o klijentu za dokumente nalaze se u Postavke, Prilagodba PDF izvoza.", "Vaše zaglavlje i podaci o klijentu za dokumente nalaze se u Podešavanja, Prilagođavanje PDF izvoza.", "Ihre Kopfzeile und Kundendaten für die Dokumente finden Sie unter Einstellungen, PDF-Export anpassen.", "Belgeler için üst bilgi ve müşteri bilgileriniz Ayarlar, PDF dışa aktarma özelleştirmesi altında tutulur.");

            // Reminders and updates
            a("Reminders and updates", "Podsjetnici i ažuriranja", "Podsjetnici i ažuriranja", "Podsetnici i ažuriranja", "Erinnerungen und Updates", "Hatırlatıcılar ve güncellemeler");
            a("Notices that work even when the app is closed", "Obavijesti koje rade i kada je aplikacija zatvorena", "Obavijesti koje rade i kada je aplikacija zatvorena", "Obaveštenja koja rade i kada je aplikacija zatvorena", "Hinweise, die auch bei geschlossener App funktionieren", "Uygulama kapalıyken de çalışan bildirimler");
            a("Missing hours banner", "Traka o nedostajućim satima", "Traka o nedostajućim satima", "Traka o nedostajućim satima", "Banner für fehlende Stunden", "Eksik saat şeridi");
            a("A banner at the top reminds you when a working day has no entry, from the hour you choose in Settings.", "Traka na vrhu podsjeća vas kada radni dan nema unos, od sata koji odaberete u postavkama.", "Traka na vrhu podsjeća vas kada radni dan nema unos, od sata koji odaberete u postavkama.", "Traka na vrhu podseća vas kada radni dan nema unos, od sata koji izaberete u podešavanjima.", "Ein Banner oben erinnert Sie, wenn ein Arbeitstag keinen Eintrag hat, ab der in den Einstellungen gewählten Uhrzeit.", "Üstteki şerit, Ayarlar'da seçtiğiniz saatten itibaren bir iş gününün kaydı olmadığında sizi uyarır.");
            a("Windows notifications", "Windows obavijesti", "Windows obavijesti", "Windows obaveštenja", "Windows-Benachrichtigungen", "Windows bildirimleri");
            a("With \"remind me when the app is closed\" on, Windows checks every 30 minutes and shows a notification (at most twice a day). It needs \"remember me\" at sign-in, so it knows whose hours to check.", "Kada je uključeno \"podsjeti me kada je aplikacija zatvorena\", Windows provjerava svakih 30 minuta i prikazuje obavijest (najviše dvaput dnevno). Potrebno je \"zapamti me\" pri prijavi da zna čije sate treba provjeriti.", "Kada je uključeno \"podsjeti me kada je aplikacija zatvorena\", Windows provjerava svakih 30 minuta i prikazuje obavijest (najviše dvaput dnevno). Potrebno je \"zapamti me\" pri prijavi da zna čije sate treba provjeriti.", "Kada je uključeno \"podseti me kada je aplikacija zatvorena\", Windows proverava na svakih 30 minuta i prikazuje obaveštenje (najviše dvaput dnevno). Potrebno je \"zapamti me\" pri prijavi da zna čije sate treba da proveri.", "Wenn \"Erinnern, wenn die App geschlossen ist\" aktiv ist, prüft Windows alle 30 Minuten und zeigt eine Benachrichtigung (höchstens zweimal täglich). Dafür ist \"Angemeldet bleiben\" nötig, damit bekannt ist, wessen Stunden zu prüfen sind.", "\"Uygulama kapalıyken hatırlat\" açıkken Windows her 30 dakikada bir kontrol eder ve bildirim gösterir (günde en fazla iki kez). Kimin saatlerinin kontrol edileceğini bilmesi için girişte \"Beni hatırla\" gerekir.");
            a("Test a notification", "Probna obavijest", "Probna obavijest", "Probno obaveštenje", "Benachrichtigung testen", "Bildirimi test et");
            a("Settings, Reminders, \"Show a test notification\" shows exactly what you will get.", "Postavke, Podsjetnici, \"Prikaži probnu obavijest\" prikazuje tačno ono što ćete dobiti.", "Postavke, Podsjetnici, \"Prikaži probnu obavijest\" prikazuje točno ono što ćete dobiti.", "Podešavanja, Podsetnici, \"Prikaži probno obaveštenje\" prikazuje tačno ono što ćete dobiti.", "Einstellungen, Erinnerungen, \"Testbenachrichtigung anzeigen\" zeigt genau, was Sie bekommen.", "Ayarlar, Hatırlatıcılar, \"Test bildirimi göster\" tam olarak alacağınız bildirimi gösterir.");
            a("New versions", "Nove verzije", "Nove verzije", "Nove verzije", "Neue Versionen", "Yeni sürümler");
            a("Windows also checks for a new version a few times a day and notifies you once per release. Clicking the notice opens the app, which offers the update. Turn it off under Settings, Updates.", "Windows nekoliko puta dnevno provjerava i novu verziju te vas obavještava jednom po izdanju. Klik na obavijest otvara aplikaciju koja nudi ažuriranje. Isključuje se u Postavke, Ažuriranja.", "Windows nekoliko puta dnevno provjerava i novu verziju te vas obavještava jednom po izdanju. Klik na obavijest otvara aplikaciju koja nudi ažuriranje. Isključuje se u Postavke, Ažuriranja.", "Windows nekoliko puta dnevno proverava i novu verziju i obaveštava vas jednom po izdanju. Klik na obaveštenje otvara aplikaciju koja nudi ažuriranje. Isključuje se u Podešavanja, Ažuriranja.", "Windows prüft außerdem mehrmals täglich auf eine neue Version und benachrichtigt Sie einmal pro Version. Ein Klick auf den Hinweis öffnet die App, die das Update anbietet. Ausschalten unter Einstellungen, Updates.", "Windows ayrıca günde birkaç kez yeni sürüm arar ve sürüm başına bir kez bildirir. Bildirime tıklamak, güncellemeyi sunan uygulamayı açar. Ayarlar, Güncellemeler bölümünden kapatılabilir.");
            a("Check now", "Provjeri odmah", "Provjeri odmah", "Proveri odmah", "Jetzt prüfen", "Şimdi denetle");
            a("Settings, Updates, \"Check for Updates\" looks right away.", "Postavke, Ažuriranja, \"Provjeri ažuriranja\" provjerava odmah.", "Postavke, Ažuriranja, \"Provjeri ažuriranja\" provjerava odmah.", "Podešavanja, Ažuriranja, \"Proveri ažuriranja\" proverava odmah.", "Einstellungen, Updates, \"Nach Updates suchen\" prüft sofort.", "Ayarlar, Güncellemeler, \"Güncellemeleri denetle\" hemen denetler.");

            // Data and the app
            a("Your data and the app", "Vaši podaci i aplikacija", "Vaši podaci i aplikacija", "Vaši podaci i aplikacija", "Ihre Daten und die App", "Verileriniz ve uygulama");
            a("Backups, appearance and troubleshooting", "Sigurnosne kopije, izgled i rješavanje problema", "Sigurnosne kopije, izgled i rješavanje problema", "Rezervne kopije, izgled i rešavanje problema", "Sicherungen, Erscheinungsbild und Fehlerbehebung", "Yedekler, görünüm ve sorun giderme");
            a("Backup and restore", "Sigurnosna kopija i vraćanje", "Sigurnosna kopija i vraćanje", "Rezervna kopija i vraćanje", "Sichern und wiederherstellen", "Yedekleme ve geri yükleme");
            a("Settings, Backup and import, saves everything to a file and restores it. Restoring never deletes anything and skips entries that already exist.", "Postavke, Sigurnosna kopija i uvoz, sprema sve u datoteku i vraća iz nje. Vraćanje nikada ništa ne briše i preskače unose koji već postoje.", "Postavke, Sigurnosna kopija i uvoz, sprema sve u datoteku i vraća iz nje. Vraćanje nikada ništa ne briše i preskače unose koji već postoje.", "Podešavanja, Rezervna kopija i uvoz, čuva sve u datoteku i vraća iz nje. Vraćanje nikada ništa ne briše i preskače unose koji već postoje.", "Einstellungen, Sicherung und Import, speichert alles in einer Datei und stellt es wieder her. Beim Wiederherstellen wird nie etwas gelöscht; vorhandene Einträge werden übersprungen.", "Ayarlar, Yedekleme ve içe aktarma, her şeyi bir dosyaya kaydeder ve geri yükler. Geri yükleme hiçbir şeyi silmez ve var olan kayıtları atlar.");
            a("Import", "Uvoz", "Uvoz", "Uvoz", "Import", "İçe aktarma");
            a("Entries can be imported from CSV or Excel files that have Date, Description and Hours columns. The app's own exports work.", "Unosi se mogu uvesti iz CSV ili Excel datoteka s kolonama Datum, Opis i Sati. Izvozi same aplikacije rade.", "Unosi se mogu uvesti iz CSV ili Excel datoteka sa stupcima Datum, Opis i Sati. Izvozi same aplikacije rade.", "Unosi se mogu uvesti iz CSV ili Excel datoteka sa kolonama Datum, Opis i Sati. Izvozi same aplikacije rade.", "Einträge lassen sich aus CSV- oder Excel-Dateien mit den Spalten Datum, Beschreibung und Stunden importieren. Die Exporte der App funktionieren.", "Kayıtlar, Tarih, Açıklama ve Saat sütunları olan CSV veya Excel dosyalarından içe aktarılabilir. Uygulamanın kendi dışa aktarmaları uygundur.");
            a("Light and dark", "Svijetla i tamna tema", "Svijetla i tamna tema", "Svetla i tamna tema", "Hell und dunkel", "Açık ve koyu");
            a("The theme button at the bottom of the sidebar switches between them; the choice is remembered.", "Dugme teme pri dnu bočne trake prebacuje između njih; izbor se pamti.", "Gumb teme pri dnu bočne trake prebacuje između njih; izbor se pamti.", "Dugme teme pri dnu bočne trake prebacuje između njih; izbor se pamti.", "Die Design-Schaltfläche unten in der Seitenleiste wechselt zwischen beiden; die Auswahl wird gespeichert.", "Kenar çubuğunun altındaki tema düğmesi ikisi arasında geçiş yapar; seçim hatırlanır.");
            a("Log files", "Datoteke zapisnika", "Datoteke zapisnika", "Datoteke dnevnika", "Protokolldateien", "Günlük dosyaları");
            a("If something goes wrong, the log is in %LOCALAPPDATA%\\DailyTaskManager\\logs. Send it along when you report a problem.", "Ako nešto pođe po zlu, zapisnik se nalazi u %LOCALAPPDATA%\\DailyTaskManager\\logs. Pošaljite ga uz prijavu problema.", "Ako nešto pođe po zlu, zapisnik se nalazi u %LOCALAPPDATA%\\DailyTaskManager\\logs. Pošaljite ga uz prijavu problema.", "Ako nešto pođe po zlu, dnevnik se nalazi u %LOCALAPPDATA%\\DailyTaskManager\\logs. Pošaljite ga uz prijavu problema.", "Wenn etwas schiefgeht, finden Sie das Protokoll unter %LOCALAPPDATA%\\DailyTaskManager\\logs. Senden Sie es mit, wenn Sie ein Problem melden.", "Bir şey ters giderse günlük %LOCALAPPDATA%\\DailyTaskManager\\logs klasöründedir. Sorun bildirirken onu da gönderin.");
            a("Language and dictation", "Jezik i diktiranje", "Jezik i diktiranje", "Jezik i diktiranje", "Sprache und Diktat", "Dil ve dikte");
            a("Interface language, and the language you speak when dictating, are chosen separately in Settings.", "Jezik sučelja i jezik na kojem diktirate biraju se zasebno u postavkama.", "Jezik sučelja i jezik na kojem diktirate biraju se zasebno u postavkama.", "Jezik interfejsa i jezik na kojem diktirate biraju se zasebno u podešavanjima.", "Oberflächensprache und die beim Diktieren gesprochene Sprache werden in den Einstellungen getrennt gewählt.", "Arayüz dili ve dikte ederken konuştuğunuz dil, Ayarlar'da ayrı ayrı seçilir.");
